$taskRoot = (Get-Item -LiteralPath 'C:\Users\605\Documents\Codex').FullName.TrimEnd('\')
$taskOutput = (Get-Item -LiteralPath 'C:\Users\605\Documents\Output').FullName.TrimEnd('\')
if ($taskRoot -ne 'C:\Users\605\Documents\Codex' -or $taskOutput -ne 'C:\Users\605\Documents\Output') { throw '根目录校验失败。' }
$taskPrefix = $taskRoot + '\'
$taskOutputPrefix = $taskOutput + '\'
$taskTag = '2026-10-29-' + [guid]::NewGuid().ToString('N').Substring(0,8)
$taskQueue = New-Object 'System.Collections.Generic.Queue[string]'
$taskQueue.Enqueue($taskRoot)
$taskFiles = @()
$taskSkipped = @()
while ($taskQueue.Count -gt 0) {
 foreach ($taskItem in Get-ChildItem -LiteralPath $taskQueue.Dequeue() -Force) {
  if (($taskItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $taskSkipped += $taskItem.FullName; continue }
  if ($taskItem.PSIsContainer) { $taskQueue.Enqueue($taskItem.FullName) }
  elseif ($taskItem.Extension -in @('.in','.exe')) { $taskFiles += $taskItem }
 }
}
$taskPlan = @()
foreach ($taskItem in $taskFiles) {
 $taskSource = [System.IO.Path]::GetFullPath($taskItem.FullName)
 if (-not $taskSource.StartsWith($taskPrefix, [System.StringComparison]::OrdinalIgnoreCase)) { throw '源文件超出授权目录。' }
 $taskRelative = $taskSource.Substring($taskPrefix.Length)
 $taskDest = [System.IO.Path]::GetFullPath((Join-Path (Join-Path $taskOutput 'Codex') $taskRelative))
 if (Test-Path -LiteralPath $taskDest) {
  $taskDest = Join-Path ([System.IO.Path]::GetDirectoryName($taskDest)) ([System.IO.Path]::GetFileNameWithoutExtension($taskDest) + '__' + $taskTag + [System.IO.Path]::GetExtension($taskDest))
 }
 if (-not $taskDest.StartsWith($taskOutputPrefix, [System.StringComparison]::OrdinalIgnoreCase) -or (Test-Path -LiteralPath $taskDest)) { throw '目标路径校验失败。' }
 $taskParent = [System.IO.Path]::GetDirectoryName($taskDest)
 while ($taskParent -and $taskParent.StartsWith($taskOutput, [System.StringComparison]::OrdinalIgnoreCase)) {
  if (Test-Path -LiteralPath $taskParent) {
   $taskParentItem = Get-Item -LiteralPath $taskParent -Force
   if (-not $taskParentItem.PSIsContainer -or ($taskParentItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw ('目标目录不是普通文件夹：' + $taskParent) }
  }
  if ($taskParent -eq $taskOutput) { break }
  $taskParent = [System.IO.Path]::GetDirectoryName($taskParent)
 }
 $taskPlan += [pscustomobject]@{ Source=$taskSource; Destination=$taskDest; Length=$taskItem.Length; SHA256=(Get-FileHash -LiteralPath $taskSource -Algorithm SHA256).Hash; Status='planned'; Error='' }
}
$taskManifest = Join-Path $taskOutput ('文件迁移清单-' + $taskTag + '.csv')
$taskPlan | Export-Csv -LiteralPath $taskManifest -NoTypeInformation -Encoding UTF8
foreach ($taskEntry in $taskPlan) {
 try {
  $taskDestDir = [System.IO.Path]::GetDirectoryName($taskEntry.Destination)
  [System.IO.Directory]::CreateDirectory($taskDestDir) | Out-Null
  Move-Item -LiteralPath $taskEntry.Source -Destination $taskEntry.Destination -ErrorAction Stop
  if ((Get-FileHash -LiteralPath $taskEntry.Destination -Algorithm SHA256).Hash -ne $taskEntry.SHA256 -or (Test-Path -LiteralPath $taskEntry.Source)) { throw '移动后完整性校验失败。' }
  $taskEntry.Status = 'verified'
 } catch {
  $taskEntry.Status = 'failed'
  $taskEntry.Error = $_.Exception.Message
 }
}
$taskPlan | Export-Csv -LiteralPath $taskManifest -NoTypeInformation -Encoding UTF8
[pscustomobject]@{ Planned=$taskPlan.Count; Verified=@($taskPlan | Where-Object Status -eq 'verified').Count; Failed=@($taskPlan | Where-Object Status -eq 'failed').Count; InCount=@($taskPlan | Where-Object { [System.IO.Path]::GetExtension($_.Source) -ieq '.in' }).Count; ExeCount=@($taskPlan | Where-Object { [System.IO.Path]::GetExtension($_.Source) -ieq '.exe' }).Count; Bytes=($taskPlan | Measure-Object Length -Sum).Sum; Manifest=$taskManifest; SkippedReparse=$taskSkipped } | ConvertTo-Json -Depth 3
$taskPlan | Where-Object Status -eq 'failed' | Select-Object Source,Destination,Error | ConvertTo-Json -Depth 3

